    LANGUAGE_WRAPPER = 'In a math contest, {alpha} students are working with two sequences {a_n} of non-negative integers and {b_n} of positive real numbers, for n = 1, 2, ..., {alpha}. Define x_n = a_n b_n. Assume there exists an integer {m} such that the following three conditions hold:\n1. (\\sum_{n=1}^{\\alpha} x_n)\\left( \\sum_{k=0}^{\\, {m}-1} \\frac{1}{(k+{m}+1)(2{m} - k)} \\right) = \\sum_{k=1}^{\\, {m}} \\frac{1}{k(2k-1)}.\n2. \\frac{\\sum_{k=1}^{\\, {m}}\\frac{1}{k(2k-1)}}{\\sum_{k=0}^{\\, {m}-1} \\frac{1}{(k+{m}+1)(2{m} - k)}} = \\sum_{n=1}^{\\alpha} x_n^2.\n3. \\left( \\sum_{k=0}^{\\, 2{m}-1} \\frac{1}{(k+2{m}+1)(4{m} - k)} \\right)\\Bigg[\\, 2\\left(\\sum_{n=1}^{\\alpha} x_n^3\\right) - 1\\Bigg] = \\sum_{k=1}^{\\, 2{m}} \\frac{1}{k(2k-1)}.\nFind the minimum possible value of \\sum_{n=1}^{\\alpha} x_n^4.\nAfter solving the above problem, please output your final answer in the following format:\n### The final answer is: $\\boxed{<your answer>}$'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose m so that alpha = 3*m + 1 is large enough to ensure non-trivial telescoping sums.
# This keeps the instance challenging and avoids tiny edge cases.
m = rng.randint(60, 250)
alpha = 3*m + 1
return {'alpha': alpha, 'm': m}

    def verifier(assign):
# Validate domain constraints and compute the unique minimum.
# We enforce that the constructed identities yield equality in Hölder/Cauchy, forcing all x_n equal.
try:
    alpha = int(assign.get('alpha'))
    m = int(assign.get('m'))
except Exception:
    # Invalid types
    return False, None
# Basic constraints
if m < 60:
    # Too small; not intended difficulty
    return False, None
if alpha != 3*m + 1:
    # The instance must satisfy the design relation
    return False, None
# Use exact rational arithmetic to avoid floating error
from fractions import Fraction
def sum_R(mm):
    # R(mm) = sum_{k=1}^mm 1/(k(2k-1))
    s = Fraction(0,1)
    for k in range(1, mm+1):
        s += Fraction(1, k*(2*k - 1))
    return s
def sum_T(mm):
    # T(mm) = sum_{k=0}^{mm-1} 1/((k+mm+1)(2mm - k))
    s = Fraction(0,1)
    for k in range(0, mm):
        s += Fraction(1, (k+mm+1)*(2*mm - k))
    return s
# Compute the key sums
Rm = sum_R(m)
Tm = sum_T(m)
# Condition 1 implies sum x_n = Rm/Tm
S1 = Rm / Tm
if S1 != alpha:
    # The identity must resolve to alpha exactly
    return False, None
# Condition 2 sets sum x_n^2 equal to the same ratio
S2 = Rm / Tm
# Condition 3 with 2m parameter sets sum x_n^3 via: (2*S3 - 1) * T(2m) = R(2m)
R2m = sum_R(2*m)
T2m = sum_T(2*m)
S3 = (R2m / T2m + Fraction(1,1)) / 2
# Verify these values satisfy the equality conditions of Hölder/Cauchy
# Hölder r=2: (sum x)^2 <= alpha * sum x^2; equality iff all x equal
if S1*S1 != alpha * S2:
    return False, None
# Hölder r=3: (sum x)^3 <= alpha^2 * sum x^3; equality iff all x equal
if S1*S1*S1 != (alpha*alpha) * S3:
    return False, None
# Therefore all x_n must be equal to S1/alpha = 1, and the minimal (indeed unique) value is sum x_n^4 = alpha * 1^4 = alpha.
answer = alpha
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
